local SettingsData = {}
local SettingsFileName = game.Players.LocalPlayer.Name .. "-NewKaitunV4.json"

function SaveSettings(key, value)
    if key ~= nil then
        SettingsData[key] = value
    end
    if not isfolder("Banana Cat Hub") then
        makefolder("Banana Cat Hub")
    end
    writefile("Banana Cat Hub/" .. SettingsFileName, HttpService:JSONEncode(SettingsData))
end

if getgenv().Config then
    SettingsData = getgenv().Config
    SaveSettings()
end

function ReadSetting()
    local ok, decoded = pcall(function()
        if not isfolder("Banana Cat Hub") then
            makefolder("Banana Cat Hub")
        end
        return HttpService:JSONDecode(readfile("Banana Cat Hub/" .. SettingsFileName))
    end)
    if ok then
        return decoded
    end
    SaveSettings()
    return ReadSetting()
end

