function AttackAOE(range, includePlayers)
    local hitList = {}
    local lastRig = nil
    local lastPart = nil
    local char = LocalPlayer.Character
    local hits = getgenv().getBladeHits(char, { char.HumanoidRootPart }, range or 80, includePlayers)
    for _, hitPart in pairs(hits) do
        local rig = CombatUtil:GetRigOfHitPart(hitPart)
        if rig then
            if ValidHitParts[hitPart.Name] then
                local targetSummoner = rig:FindFirstChild("Summoner")
                local selfSummoner = char:FindFirstChild("Summoner")
                local selfPlayer = game.Players:GetPlayerFromCharacter(char)
                local notOwnSummon = not selfSummoner or rig ~= selfSummoner.Value.Character
                local notSummonedBySelf = not selfPlayer or not targetSummoner or targetSummoner.Value ~= selfPlayer
                if notOwnSummon and notSummonedBySelf and CombatUtil:IsVulnerable(rig) then
                    lastRig = rig
                    lastPart = hitPart
                    table.insert(hitList, { rig, hitPart })
                end
            end
        else
            warn("No rig found for hit part:", hitPart)
        end
    end
    local payload = {}
    for _, entry in pairs(hitList) do
        table.insert(payload, entry)
    end
    table.insert(payload, { lastRig, lastPart })
    if #payload > 0 then
        return payload
    end
end
