    local bxorByte = (bit32 and bit32.bxor) or (bit and bit.bxor) or function(a, b)
        local res, bitVal = 0, 1
        while a > 0 or b > 0 do
            local ra, rb = a % 2, b % 2
            if ra ~= rb then
                res = res + bitVal
            end
            a = (a - ra) / 2
            b = (b - rb) / 2
            bitVal = bitVal * 2
        end
        return res
    end

    local JOBID_KEY = "O\022\000u\144W~\151\158V(\0111\2333\138dF_\188>&\193\182\210\200\173kG\205\196\184"
    local B64_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local B64_LOOKUP = {}
    for idx = 1, #B64_ALPHABET do
        B64_LOOKUP[string.byte(B64_ALPHABET, idx)] = idx - 1
    end

    local function deriveJobKeystream(key, salt, length)
        local src = key .. salt .. string.reverse(key) .. string.char(#key % 256, #salt % 256)
        local mixed = {}
        for idx = 1, #src do
            local b = bxorByte(string.byte(src, idx), (idx * 29) % 256)
            mixed[idx] = (b + (idx * 7) % 256) % 256
        end
        local mixedLen = #mixed
        local ks, state = {}, 0
        for idx = 1, length do
            local kb = mixed[(idx - 1) % mixedLen + 1]
            state = (state + kb + idx + (idx * 11) % 256) % 256
            ks[idx] = (kb + state + idx * 17 + (kb * 3) % 256) % 256
        end
        return ks
    end

    local function base64Encode(data)
        local out = {}
        local len = #data
        local idx = 1
        while idx <= len do
            local b1 = string.byte(data, idx)
            local b2 = (idx + 1 <= len) and string.byte(data, idx + 1) or 0
            local b3 = (idx + 2 <= len) and string.byte(data, idx + 2) or 0
            local n = b1 * 65536 + b2 * 256 + b3
            local c1 = math.floor(n / 262144) % 64 + 1
            local c2 = math.floor(n / 4096) % 64 + 1
            local c3 = math.floor(n / 64) % 64 + 1
            local c4 = n % 64 + 1
            out[#out + 1] = string.sub(B64_ALPHABET, c1, c1)
            out[#out + 1] = string.sub(B64_ALPHABET, c2, c2)
            out[#out + 1] = (idx + 1 <= len) and string.sub(B64_ALPHABET, c3, c3) or "="
            out[#out + 1] = (idx + 2 <= len) and string.sub(B64_ALPHABET, c4, c4) or "="
            idx = idx + 3
        end
        return table.concat(out)
    end

    local function base64Decode(data)
        local out = {}
        local len = #data
        local idx = 1
        while idx + 3 <= len do
            local c1 = string.byte(data, idx)
            local c2 = string.byte(data, idx + 1)
            local c3 = string.byte(data, idx + 2)
            local c4 = string.byte(data, idx + 3)
            local n = (B64_LOOKUP[c1] or 0) * 262144
                + (B64_LOOKUP[c2] or 0) * 4096
                + (B64_LOOKUP[c3] or 0) * 64
                + (B64_LOOKUP[c4] or 0)
            out[#out + 1] = string.char(math.floor(n / 65536) % 256)
            if c3 ~= 61 then
                out[#out + 1] = string.char(math.floor(n / 256) % 256)
            end
            if c4 ~= 61 then
                out[#out + 1] = string.char(n % 256)
            end
            idx = idx + 4
        end
        return table.concat(out)
    end

    local function encodeJobId(plainJobId, customSalt)
        local salt = customSalt
        if not salt then
            local saltBytes = {}
            for idx = 1, 16 do
                saltBytes[idx] = string.char(math.random(0, 255))
            end
            salt = table.concat(saltBytes)
        end
        local cur = plainJobId
        for roundIdx = 1, 3 do
            local roundKey = JOBID_KEY .. string.char(48 + roundIdx)
            local ks = deriveJobKeystream(roundKey, salt, #cur)
            local state = (#JOBID_KEY + #salt + roundIdx * 37 + 91) % 256
            local out = {}
            for idx = 1, #cur do
                local sb = string.byte(salt, (idx + roundIdx - 2) % 16 + 1)
                local kk = ks[idx]
                state = (state + kk + sb + idx + roundIdx) % 256
                local enc = bxorByte(string.byte(cur, idx), kk)
                enc = (enc + state + sb) % 256
                enc = bxorByte(enc, (idx * 31 + sb + roundIdx * 9) % 256)
                enc = (enc + (kk * 5) % 256) % 256
                out[idx] = string.char(enc)
            end
            cur = table.concat(out)
        end
        return "BananaCat-" .. base64Encode(salt .. cur)
    end

    local function decodeJobId(encryptedJobId)
        local stripped = encryptedJobId
        if string.sub(stripped, 1, 10) == "BananaCat-" then
            stripped = string.sub(stripped, 11)
        end
        local raw = base64Decode(stripped)
        if #raw < 16 then
            return ""
        end
        local salt = string.sub(raw, 1, 16)
        local cur = string.sub(raw, 17)
        for roundIdx = 3, 1, -1 do
            local roundKey = JOBID_KEY .. string.char(48 + roundIdx)
            local ks = deriveJobKeystream(roundKey, salt, #cur)
            local state = (#JOBID_KEY + #salt + roundIdx * 37 + 91) % 256
            local out = {}
            for idx = 1, #cur do
                local sb = string.byte(salt, (idx + roundIdx - 2) % 16 + 1)
                local kk = ks[idx]
                state = (state + kk + sb + idx + roundIdx) % 256
                local db = (string.byte(cur, idx) - (kk * 5) % 256 + 256) % 256
                db = bxorByte(db, (idx * 31 + sb + roundIdx * 9) % 256)
                db = (db - state - sb + 512) % 256
                db = bxorByte(db, kk)
                out[idx] = string.char(db)
            end
            cur = table.concat(out)
        end
        return cur
    end

