    hopLessButton.MouseButton1Click:Connect(function()
        getgenv().SetStatus("Hopping to less server...")
        pcall(function()
            require(game:GetService("ReplicatedStorage").Notification).new("<Color=Red>Banana Hub : Hop Server<Color=/>"):Display()
            local placeId = game.PlaceId
            local visitedIds = {}
            local nextCursor = ""
            local currentHour = os.date("!*t").hour

            local loadedOk = pcall(function()
                visitedIds = HttpService:JSONDecode(readfile("Banana Cat Hub/NotSameServers.json"))
            end)
            if not loadedOk then
                table.insert(visitedIds, currentHour)
                writefile("Banana Cat Hub/NotSameServers.json", HttpService:JSONEncode(visitedIds))
            end

            local function TPReturnerLess()
                local url = "https://games.roblox.com/v1/games/" .. placeId .. "/servers/Public?sortOrder=Asc&limit=100"
                if nextCursor ~= "" then
                    url = url .. "&cursor=" .. nextCursor
                end
                local response = HttpService:JSONDecode(game:HttpGet(url))
                if response.nextPageCursor and response.nextPageCursor ~= "null" and response.nextPageCursor ~= nil then
                    nextCursor = response.nextPageCursor
                end
                local index = 0
                for _, server in pairs(response.data) do
                    local canJoin = true
                    local serverId = tostring(server.id)
                    if tonumber(server.maxPlayers) > tonumber(server.playing) then
                        for _, saved in pairs(visitedIds) do
                            if index ~= 0 then
                                if serverId == tostring(saved) then
                                    canJoin = false
                                end
                            elseif tonumber(currentHour) ~= tonumber(saved) then
                                pcall(function()
                                    delfile("Banana Cat Hub/NotSameServers.json")
                                    visitedIds = {}
                                    table.insert(visitedIds, currentHour)
                                end)
                            end
                            index = index + 1
                        end
                        if canJoin then
                            table.insert(visitedIds, serverId)
                            wait()
                            pcall(function()
                                writefile("Banana Cat Hub/NotSameServers.json", HttpService:JSONEncode(visitedIds))
                                wait()
                                getgenv().limit_type("clearAll")
                                game:GetService("TeleportService"):TeleportToPlaceInstance(placeId, serverId, game.Players.LocalPlayer)
                            end)
                            wait(4)
                        end
                    end
                end
            end

            local function HopServerLess()
                while wait() do
                    pcall(function()
                        TPReturnerLess()
                        if nextCursor ~= "" then
                            TPReturnerLess()
                        end
                    end)
                end
            end

            HopServerLess()
        end)
    end)

