    local function fetchRecentServers(eventName)
        local res = nil
        local _, err = pcall(function()
            local url = string.format("%s/data/recent?name=%s&limit=%s", "https://raw.banana-hub.xyz/api", eventName, 100):gsub(" ", "%%20")
            res = ExploitReq({
                Url = url,
                Method = "GET",
            })
        end)
        if err or not res then
            return false
        end
        return res.Body
    end

    local lastSpecialHopTime = nil

    function SpecialHop(eventName)
        if getgenv().Key and #getgenv().Key == 32 then
            return
        end
        if lastSpecialHopTime and tick() - lastSpecialHopTime < 5 then
            return
        end
        local body = fetchRecentServers(eventName)
        if not body then
            return
        end
        local servers = HttpService:JSONDecode(body)
        local matched = {}
        for idx, entry in next, servers.data do
            if entry and entry.name == eventName then
                table.insert(matched, idx)
            end
        end
        lastSpecialHopTime = tick()
        if #matched > 0 then
            local tried = {}
            for _, entry in next, servers.data do
                if entry and entry.name == eventName then
                    local jobId = entry.jobid
                    local playerCount = entry.Players
                    local placeId = entry.placeid
                    if string.find(jobId, "BananaCat") then
                        jobId = decodeJobId(jobId)
                    end
                    local hasRoom = (not playerCount) or (playerCount < game.Players.MaxPlayers)
                    local samePlace = (not placeId) or (game.PlaceId == placeId)
                    if jobId and jobId ~= game.JobId and not tableFind(tried, jobId) and not SettingsData[jobId] and hasRoom and samePlace then
                        table.insert(tried, jobId)
                        game:GetService("ReplicatedStorage").__ServerBrowser:InvokeServer("teleport", tostring(jobId))
                        SaveSettings(tostring(jobId), true)
                        getgenv().limit_type("clearAll")
                    end
                end
            end
        end
    end

